public with sharing class CanyonHealthProbe {
    public static String marker() {
        return 'canyon health fixture';
    }
}

@IsTest
private class CanyonHealthProbeTest {
    @IsTest
    static void markerIsLocalAndBounded() {
        System.assertEquals('canyon health fixture', CanyonHealthProbe.marker());
    }
}

const { decisionFor } = require('./src/request-approval');

test('bounded read remains safe', () => {
    expect(decisionFor({ effect: 'read' })).toBe('allow');
});

test('destruction is reviewed', () => {
    expect(decisionFor({ effect: 'delete' })).toBe('confirm');
});

function decisionFor(request) {
    return request.effect === 'read' ? 'allow' : 'confirm';
}
module.exports = { decisionFor };
